specifications.definition:
fun r =>
  { input := if CapDAG.unconstrainedMedia r.input then CapDAG.Ask.unknown else CapDAG.Ask.covers r.input,
    output := CapDAG.Ask.within r.output, tags := r.other, effect := r.effect }

fun candidate request =>
  have p := CapDAG.capScore candidate;
  have r := CapDAG.capScore request;
  if r ≤ p then (0, p - r) else (1, r - p)
